# -*- coding: utf-8 -*-
"""Indonesia / IPA Kelas 8（Fase D。Buku Siswa IPA Kelas VIII Kurikulum Merdeka edisi revisi）"""
from id_sci import H, nq, num


def f_usaha(R):
    k = R.choice(["W", "Ek", "Ep", "P"])
    if k == "W":
        F = R.choice([10, 20, 25, 40, 50, 80])
        s = R.choice([2, 3, 4, 5, 8, 10])
        return nq("Sebuah lemari didorong dengan gaya %d N sehingga berpindah %d m. Berapa usaha yang dilakukan?" % (F, s), F * s, [F / s, F + s, F * s * 10], "J", "W = F × s = %d × %d = %d J." % (F, s, F * s))
    if k == "Ek":
        m = R.choice([2, 4, 5, 10, 50, 60])
        v = R.choice([2, 3, 4, 5, 6, 10])
        return nq("Benda bermassa %d kg bergerak dengan kecepatan %d m/s. Berapa energi kinetiknya?" % (m, v), m * v * v / 2, [m * v, m * v * v, m * v / 2], "J", "Ek = ½ × m × v² = ½ × %d × %d² = %s J." % (m, v, num(m * v * v / 2)))
    if k == "Ep":
        obj, m = R.choice([("buah kelapa", 1), ("buah kelapa", 2), ("pot bunga", 3), ("pot bunga", 5), ("karung beras", 10), ("karung beras", 20), ("kotak kayu", 15)])
        h = R.choice([2, 4, 5, 8, 10, 15])
        return nq("Sebuah %s bermassa %d kg berada %d m di atas tanah. Berapa energi potensialnya? (g = 10 m/s²)" % (obj, m, h), m * 10 * h, [m * h, m * 10, m * h / 10], "J", "Ep = m × g × h = %d × 10 × %d = %d J." % (m, h, m * 10 * h))
    W = R.choice([600, 1200, 1500, 2400, 3000, 6000])
    t = R.choice([2, 3, 4, 5, 10, 20])
    return nq("Seorang pekerja melakukan usaha %s J dalam %d s. Berapa dayanya?" % (num(W), t), W / t, [W * t, t / W * 1000, W - t], "W", "P = W ÷ t = %s ÷ %d = %s W." % (num(W), t, num(W / t)))


def f_tuas(R):
    k = R.choice(["KM", "F", "katrol", "bidang"])
    if k == "KM":
        lk = R.choice([1, 1.5, 2, 2.5, 3])
        lb = R.choice([0.25, 0.5])
        return nq("Sebuah tuas memiliki lengan kuasa %s m dan lengan beban %s m. Berapa keuntungan mekanisnya?" % (num(lk), num(lb)), lk / lb, [lb / lk, lk * lb, lk + lb], "",
                  "KM = lengan kuasa ÷ lengan beban = %s ÷ %s = %s." % (num(lk), num(lb), num(lk / lb)))
    if k == "F":
        w = R.choice([400, 600, 800, 1000, 1200])
        lb = R.choice([0.5, 1])
        lk = R.choice([2, 2.5, 4])
        F = w * lb / lk
        return nq("Batu seberat %s N diangkat dengan tuas. Lengan beban %s m dan lengan kuasa %s m. Berapa gaya kuasa yang diperlukan?" % (num(w), num(lb), num(lk)), F,
                  [w * lk / lb, w / lb, w - lk], "N", "F × lk = w × lb → F = %s × %s ÷ %s = %s N." % (num(w), num(lb), num(lk), num(F)))
    if k == "katrol":
        w = R.choice([200, 300, 500, 800])
        n = R.choice([("katrol tetap", 1), ("katrol bebas", 2), ("sistem katrol dengan 4 tali penopang", 4)])
        return nq("Beban %d N diangkat memakai %s. Berapa gaya minimal yang diperlukan (gesekan diabaikan)?" % (w, n[0]), w / n[1], [w * n[1], w / (n[1] * 2) if n[1] > 1 else w * 2, w + n[1]], "N",
                  "Keuntungan mekanis %s adalah %d, jadi F = %d ÷ %d = %s N." % (n[0], n[1], w, n[1], num(w / n[1])))
    h = R.choice([1, 1.5, 2])
    s = R.choice([4, 5, 6, 8])
    w = R.choice([400, 600, 900, 1200])
    return nq("Peti seberat %d N didorong naik bidang miring sepanjang %d m ke ketinggian %s m. Berapa gaya dorong minimal (gesekan diabaikan)?" % (w, s, num(h)), w * h / s,
              [w * s / h, w / s, w * h], "N", "F × s = w × h → F = %d × %s ÷ %d = %s N." % (w, num(h), s, num(w * h / s)))


def f_tekanan(R):
    k = R.choice(["padat", "hidro", "pascal", "archimedes"])
    if k == "padat":
        F = R.choice([200, 300, 500, 600, 800, 1000])
        A = R.choice([0.02, 0.05, 0.1, 0.2, 0.5])
        return nq("Sebuah kotak dengan gaya berat %d N terletak di lantai. Luas alasnya %s m². Berapa tekanannya pada lantai?" % (F, num(A)), F / A, [F * A, A / F * 1e5, F - A], "Pa",
                  "p = F ÷ A = %d ÷ %s = %s Pa." % (F, num(A), num(F / A)))
    if k == "hidro":
        h = R.choice([0.5, 1, 2, 3, 5, 10])
        return nq("Berapa tekanan hidrostatis air pada kedalaman %s m? (ρ air = 1.000 kg/m³, g = 10 m/s²)" % num(h), 1000 * 10 * h, [1000 * h, 10 * h, 1000 * 10 / h], "Pa",
                  "ph = ρ × g × h = 1.000 × 10 × %s = %s Pa." % (num(h), num(1000 * 10 * h)))
    if k == "pascal":
        A1 = R.choice([0.01, 0.02, 0.05])
        r = R.choice([10, 20, 50, 100])
        A2 = A1 * r
        F2 = R.choice([5000, 8000, 10000, 20000])
        F1 = F2 / r
        return nq("Dongkrak hidrolik memiliki penampang kecil %s m² dan penampang besar %s m². Berapa gaya yang diperlukan untuk mengangkat mobil seberat %s N?" % (num(A1), num(A2), num(F2)), F1,
                  [F2 * r, F2 / A1, F2 - r], "N", "F1 ÷ A1 = F2 ÷ A2 → F1 = %s × %s ÷ %s = %s N." % (num(F2), num(A1), num(A2), num(F1)))
    V = R.choice([0.001, 0.002, 0.005, 0.01, 0.02])
    return nq("Sebuah benda bervolume %s m³ tercelup seluruhnya dalam air. Berapa gaya ke atas (gaya apung) yang dialaminya? (ρ air = 1.000 kg/m³, g = 10 m/s²)" % num(V), 1000 * 10 * V,
              [1000 * V, 10 * V, 1000 * 10 / V], "N", "FA = ρ × g × V = 1.000 × 10 × %s = %s N." % (num(V), num(1000 * 10 * V)))


def f_gelombang(R):
    k = R.choice(["f", "T", "v", "lam"])
    if k == "f":
        n = R.choice([20, 30, 40, 60, 100])
        t = R.choice([4, 5, 10, 20])
        return nq("Sebuah bandul berayun %d kali dalam %d s. Berapa frekuensinya?" % (n, t), n / t, [t / n, n * t, n - t], "Hz", "f = n ÷ t = %d ÷ %d = %s Hz." % (n, t, num(n / t)))
    if k == "T":
        n = R.choice([10, 20, 25, 50])
        t = R.choice([5, 10, 20])
        return nq("Sebuah pegas bergetar %d kali dalam %d s. Berapa periodenya?" % (n, t), t / n, [n / t, n * t, t + n], "s", "T = t ÷ n = %d ÷ %d = %s s." % (t, n, num(t / n)))
    if k == "v":
        lam = R.choice([0.5, 1, 1.5, 2, 4])
        f = R.choice([2, 4, 5, 10, 20])
        return nq("Gelombang di tali memiliki panjang gelombang %s m dan frekuensi %d Hz. Berapa cepat rambatnya?" % (num(lam), f), lam * f, [lam / f, f / lam, lam + f], "m/s",
                  "v = λ × f = %s × %d = %s m/s." % (num(lam), f, num(lam * f)))
    v = R.choice([340, 1500])
    f = R.choice([170, 340, 500, 680, 850])
    med = "udara" if v == 340 else "air"
    return nq("Bunyi berfrekuensi %d Hz merambat di %s dengan kecepatan %s m/s. Berapa panjang gelombangnya?" % (f, med, num(v)), v / f, [v * f, f / v, v - f if v > f else f - v], "m",
              "λ = v ÷ f = %s ÷ %d = %s m." % (num(v), f, num(v / f)))


